def solve(xs, k):
    if not xs or k <= 0:
        return []

    n = len(xs)
    if n < k:
        return []

    max_val = float('-inf')
    result = []

    # Initialize the first window
    current_max = max(xs[:k])
    result.append(current_max)

    # Iterate through the rest of the list
    for i in range(k, n):
        # Update the current window maximum
        if xs[i] > current_max:
            current_max = xs[i]

